"""Programmatic, deterministic PDF fixtures (synthetic - generated by this code, not real documents).

Ground truth is known *by construction*: the datasets below are the exact cell strings that get
printed into the PDFs, so extraction results can be compared cell-for-cell.

reportlab is used only to *create* fixtures (requirements-dev.txt); the application itself does not need it.
"""
from __future__ import annotations

import io
import random
from pathlib import Path
from typing import List, Optional, Sequence

import numpy as np
from PIL import Image, ImageFilter

import pymupdf

from reportlab.lib import colors
from reportlab.lib.pagesizes import A4, landscape
from reportlab.platypus import PageBreak, Paragraph, SimpleDocTemplate, Spacer, Table, TableStyle
from reportlab.lib.styles import getSampleStyleSheet

INVOICE_HEADERS = [
    "Invoice No", "Date", "Customer", "City", "Item", "Category",
    "Qty", "Unit Price", "Discount", "Tax", "Amount", "Status",
]
_CUSTOMERS = ["Asha Traders", "Kiran Stores", "Meera Foods", "Ravi Agro", "Sita Mills", "Balu Hardware", "Lakshmi Textiles", "Gopal Dairy"]
_CITIES = ["Anantapur", "Hyderabad", "Chennai", "Pune", "Bengaluru", "Kadapa", "Tirupati"]
_ITEMS = [("Seed Pack", "Agro"), ("Drip Pipe", "Irrigation"), ("Fertiliser", "Agro"), ("Sprayer", "Equipment"), ("Mulch Sheet", "Agro"), ("Water Pump", "Equipment")]
_STATUS = ["Paid", "Pending", "Overdue"]


def invoice_dataset(n_rows: int, seed: int = 7, iso_dates: bool = True) -> List[List[str]]:
    """Rows of 12 string cells. Dates use days > 12 in at least some rows (so dd/mm order is decidable)."""
    rng = random.Random(seed)
    rows: List[List[str]] = []
    for i in range(1, n_rows + 1):
        item, cat = rng.choice(_ITEMS)
        qty = rng.randint(1, 40)
        price = round(rng.uniform(50, 900), 2)
        disc = rng.choice([0, 0, 5, 10])
        gross = qty * price
        net = gross * (1 - disc / 100)
        tax = round(net * 0.18, 2)
        amount = round(net + tax, 2)
        day, month = rng.randint(13, 28), rng.randint(1, 12)
        date = f"2026-{month:02d}-{day:02d}" if iso_dates else f"{day:02d}/{month:02d}/2026"
        rows.append([
            f"INV-{1000 + i}", date, rng.choice(_CUSTOMERS), rng.choice(_CITIES), item, cat,
            str(qty), f"{price:.2f}", f"{disc}%", f"{tax:.2f}", f"{amount:.2f}", rng.choice(_STATUS),
        ])
    return rows


def simple_dataset(n_rows: int = 12) -> tuple:
    headers = ["Code", "Product", "Quantity", "Price"]
    rows = [[f"{i:03d}", f"Product {chr(64 + (i % 26) + 1)}", str(i * 3), f"{i * 12.5:.2f}"] for i in range(1, n_rows + 1)]
    return headers, rows


# ----------------------------------------------------------------------------- digital PDFs

def make_table_pdf(
    path: Path,
    headers: Sequence[str],
    rows: Sequence[Sequence[str]],
    rows_per_page: int = 25,
    grid: bool = True,
    repeat_header: bool = True,
    title: Optional[str] = None,
    page_footer: bool = True,
    landscape_page: bool = True,
    font_size: float = 8,
    extra_tables: Optional[List[tuple]] = None,
    col_widths: Optional[Sequence[float]] = None,
) -> Path:
    """Digital PDF with one table split over pages by `rows_per_page` (header optionally repeated)."""
    pagesize = landscape(A4) if landscape_page else A4
    styles = getSampleStyleSheet()
    flow = []
    if title:
        flow += [Paragraph(title, styles["Title"]), Spacer(1, 8)]

    def footer(canvas, doc):
        if page_footer:
            canvas.saveState()
            canvas.setFont("Helvetica", 8)
            canvas.drawString(30, 18, "Confidential - Synthetic Test Report")
            canvas.drawRightString(pagesize[0] - 30, 18, f"Page {doc.page}")
            canvas.restoreState()

    def build_table(h, r):
        data = [list(h)] + [list(x) for x in r]
        t = Table(data, repeatRows=1 if repeat_header else 0, colWidths=col_widths)
        style = [
            ("FONTSIZE", (0, 0), (-1, -1), font_size),
            ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
            ("TOPPADDING", (0, 0), (-1, -1), 4),
            ("LEFTPADDING", (0, 0), (-1, -1), 5),
            ("RIGHTPADDING", (0, 0), (-1, -1), 5),
        ]
        if grid:
            style.append(("GRID", (0, 0), (-1, -1), 0.5, colors.black))
        t.setStyle(TableStyle(style))
        return t

    # Split manually per page so page breaks are deterministic (and header repeated explicitly)
    chunks = [rows[i:i + rows_per_page] for i in range(0, len(rows), rows_per_page)] or [[]]
    for ci, chunk in enumerate(chunks):
        if ci > 0:
            flow.append(PageBreak())
        if ci == 0 or repeat_header:
            flow.append(build_table(headers, chunk))
        else:
            data = [list(x) for x in chunk]
            t = Table(data, colWidths=col_widths)
            st = [("FONTSIZE", (0, 0), (-1, -1), font_size), ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
                  ("TOPPADDING", (0, 0), (-1, -1), 4), ("LEFTPADDING", (0, 0), (-1, -1), 5), ("RIGHTPADDING", (0, 0), (-1, -1), 5)]
            if grid:
                st.append(("GRID", (0, 0), (-1, -1), 0.5, colors.black))
            t.setStyle(TableStyle(st))
            flow.append(t)

    for (h2, r2, caption) in (extra_tables or []):
        flow.append(PageBreak())
        if caption:
            flow += [Paragraph(caption, styles["Heading2"]), Spacer(1, 6)]
        flow.append(build_table(h2, r2))

    doc = SimpleDocTemplate(str(path), pagesize=pagesize, leftMargin=30, rightMargin=30, topMargin=36, bottomMargin=36)
    doc.build(flow, onFirstPage=footer, onLaterPages=footer)
    return path


def make_prose_pdf(path: Path, paragraphs: int = 4) -> Path:
    styles = getSampleStyleSheet()
    text = ("This page contains ordinary running text and no table. It describes the quarterly review "
            "meeting, the agenda items discussed, and the follow-up actions agreed by the committee. ") * 4
    flow = [Paragraph("Meeting Notes", styles["Title"])]
    for _ in range(paragraphs):
        flow += [Paragraph(text, styles["BodyText"]), Spacer(1, 10)]
    SimpleDocTemplate(str(path), pagesize=A4).build(flow)
    return path


def make_blank_pdf(path: Path, pages: int = 1) -> Path:
    doc = pymupdf.open()
    for _ in range(pages):
        doc.new_page()
    doc.save(str(path))
    doc.close()
    return path


# ----------------------------------------------------------------------------- scanned / mixed

def _degrade(img: Image.Image, rotate_deg: float, noise: float, blur: float) -> Image.Image:
    if rotate_deg:
        img = img.rotate(rotate_deg, resample=Image.BICUBIC, expand=False, fillcolor=(255, 255, 255))
    if blur:
        img = img.filter(ImageFilter.GaussianBlur(blur))
    if noise:
        arr = np.asarray(img, dtype=np.int16)
        rng = np.random.default_rng(1234)
        arr = np.clip(arr + rng.normal(0, noise, arr.shape), 0, 255).astype(np.uint8)
        img = Image.fromarray(arr)
    return img


def make_scanned_pdf(src_pdf: Path, dst_pdf: Path, dpi: int = 220, rotate_deg: float = 0.0,
                     noise: float = 0.0, blur: float = 0.0, pages: Optional[Sequence[int]] = None) -> Path:
    """Rasterise `src_pdf` pages and embed the pictures into a NEW pdf with no text layer."""
    src = pymupdf.open(str(src_pdf))
    out = pymupdf.open()
    try:
        for i in (pages if pages is not None else range(src.page_count)):
            page = src.load_page(i)
            pix = page.get_pixmap(matrix=pymupdf.Matrix(dpi / 72, dpi / 72), alpha=False)
            img = Image.frombytes("RGB", (pix.width, pix.height), pix.samples)
            img = _degrade(img, rotate_deg, noise, blur)
            buf = io.BytesIO()
            img.save(buf, format="JPEG", quality=88)
            newp = out.new_page(width=page.rect.width, height=page.rect.height)
            newp.insert_image(newp.rect, stream=buf.getvalue())
        out.save(str(dst_pdf))
    finally:
        src.close()
        out.close()
    return dst_pdf


def combine_pdfs(parts: Sequence[Path], dst: Path) -> Path:
    out = pymupdf.open()
    for p in parts:
        d = pymupdf.open(str(p))
        out.insert_pdf(d)
        d.close()
    out.save(str(dst))
    out.close()
    return dst


# ----------------------------------------------------------------------------- bad files

def make_corrupt_pdf(path: Path) -> Path:
    path.write_bytes(b"%PDF-1.7\n1 0 obj\n<< /Type /Catalog /Pages 99 0 R >>\nendobj\nthis is not a real pdf body \x00\x01\x02" * 3)
    return path


def make_not_pdf(path: Path) -> Path:
    path.write_bytes(b"PK\x03\x04 this is a zip-like file pretending to be a pdf")
    return path


def make_encrypted_pdf(src: Path, dst: Path, password: str = "secret") -> Path:
    d = pymupdf.open(str(src))
    d.save(str(dst), encryption=pymupdf.PDF_ENCRYPT_AES_256, user_pw=password, owner_pw=password + "_o")
    d.close()
    return dst


def make_many_pages_pdf(path: Path, n_pages: int = 51) -> Path:
    doc = pymupdf.open()
    for i in range(n_pages):
        p = doc.new_page()
        p.insert_text((72, 72), f"Page {i + 1}")
    doc.save(str(path))
    doc.close()
    return path
